        bid.state = BidState.CLOSED;

        address sender = _msgSenderForMarket(bid.marketplaceId);
        require(sender == bid.lender, "only lender can close loan");

@>      collateralManager.lenderClaimCollateral(_bidId);

        emit LoanClosed(_bidId);
